def calc(expr):
    tokens = []
    i = 0
    n = len(expr)
    while i < n:
        c = expr[i]
        if c.isspace():
            i += 1
            continue
        if c.isdigit():
            j = i
            while j < n and expr[j].isdigit():
                j += 1
            tokens.append(('num', int(expr[i:j])))
            i = j
            continue
        if c in '+-*/()':
            tokens.append((c, c))
            i += 1
            continue
        raise ValueError(f"Unexpected character: {c}")

    pos = 0

    def peek():
        nonlocal pos
        if pos < len(tokens):
            return tokens[pos]
        return None

    def advance():
        nonlocal pos
        tok = tokens[pos]
        pos += 1
        return tok

    def parse_primary():
        tok = peek()
        if tok is None:
            raise ValueError("Unexpected end of expression")
        if tok[0] == 'num':
            advance()
            return tok[1]
        if tok[0] == '(':
            advance()
            val = parse_expr()
            tok2 = peek()
            if tok2 is None or tok2[0] != ')':
                raise ValueError("Expected closing parenthesis")
            advance()
            return val
        raise ValueError(f"Unexpected token: {tok}")

    def parse_factor():
        neg_count = 0
        while True:
            tok = peek()
            if tok is not None and tok[0] == '-':
                neg_count += 1
                advance()
            else:
                break
        val = parse_primary()
        if neg_count % 2 == 1:
            val = -val
        return val

    def parse_term():
        val = parse_factor()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('*', '/'):
                op = tok[0]
                advance()
                rhs = parse_factor()
                if op == '*':
                    val = val * rhs
                else:
                    # integer division truncating toward zero
                    q = abs(val) // abs(rhs)
                    if (val < 0) != (rhs < 0):
                        q = -q
                    val = q
            else:
                break
        return val

    def parse_expr():
        val = parse_term()
        while True:
            tok = peek()
            if tok is not None and tok[0] in ('+', '-'):
                op = tok[0]
                advance()
                rhs = parse_term()
                if op == '+':
                    val = val + rhs
                else:
                    val = val - rhs
            else:
                break
        return val

    result = parse_expr()
    if pos != len(tokens):
        raise ValueError("Unexpected trailing tokens")
    return result

